  it('renders information for a generic event on the main thread', async function() {
    const parsedTrace = await TraceLoader.traceEngine(this, 'web-dev-with-commit.json.gz');
    const detailsView = new Timeline.TimelineDetailsView.TimelineDetailsPane(mockViewDelegate);
    renderElementIntoDOM(detailsView);
    const evalScriptEvent = allThreadEntriesInTrace(parsedTrace).find(event => {
      return event.name === Trace.Types.Events.Name.EVALUATE_SCRIPT && event.dur && event.dur > 2000;
    });
    assert.isOk(evalScriptEvent);
    await detailsView.setModel(
        {parsedTrace, selectedEvents: null, eventToRelatedInsightsMap: null, entityMapper: null});
    const selection = Timeline.TimelineSelection.selectionFromEvent(evalScriptEvent);
    await detailsView.setSelection(selection);
    const detailsContentElement = detailsView.getDetailsContentElementForTest();

    assert.strictEqual(
        detailsContentElement.querySelector<HTMLElement>('.timeline-details-chip-title')?.innerText, 'Evaluate script');

    // Ensure we show the pie chart time breakdown
    assert.isTrue(detailsContentElement.innerText.includes('Aggregated time'));
  });

  it('updates the range details when the user has a range selected', async function() {
    const parsedTrace = await TraceLoader.traceEngine(this, 'web-dev-with-commit.json.gz');
    const detailsView = new Timeline.TimelineDetailsView.TimelineDetailsPane(mockViewDelegate);
    renderElementIntoDOM(detailsView);
    await detailsView.setModel({
      parsedTrace,
      // We have to set selected events for the range selection UI to be drawn
      // (without the set of events we can't generate the range stats)
      selectedEvents: allThreadEntriesInTrace(parsedTrace),
      eventToRelatedInsightsMap: null,
      entityMapper: null,
    });
    const bounds = Trace.Helpers.Timing.traceWindowMilliSeconds(parsedTrace.data.Meta.traceBounds);
    const selection = Timeline.TimelineSelection.selectionFromRangeMilliSeconds(
        bounds.min,
        bounds.max,
    );
    await detailsView.setSelection(selection);
    await raf();

    const detailsContentElement = detailsView.getDetailsContentElementForTest();
    const rangeSummaryWidget = detailsContentElement.querySelector('devtools-widget');
    const categorySummaryWidget = rangeSummaryWidget?.shadowRoot?.querySelector('devtools-widget.timeline-summary');
    const range = categorySummaryWidget?.querySelector<HTMLElement>('.summary-range');
    assert.strictEqual(range?.innerText, 'Range: 0 ms – 5.39 s');
  });

  it('correctly creates an event widget using the static method and hides the tabbed header', async function() {
    const parsedTrace = await TraceLoader.traceEngine(this, 'web-dev-with-commit.json.gz');

    const evalScriptEvent = allThreadEntriesInTrace(parsedTrace).find(event => {
      return event.name === Trace.Types.Events.Name.EVALUATE_SCRIPT && event.dur && event.dur > 2000;
    });
    assert.isOk(evalScriptEvent);

    const detailsView = Timeline.TimelineDetailsView.TimelineDetailsPane.makeEventWidget(
        evalScriptEvent,
        parsedTrace,
    );
    renderElementIntoDOM(detailsView);
    await doubleRaf();

    const detailsContentElement = detailsView.getDetailsContentElementForTest();
    assert.strictEqual(
        detailsContentElement.querySelector<HTMLElement>('.timeline-details-chip-title')?.innerText, 'Evaluate script');

    const tabbedPaneHeader =
        detailsView.element.querySelector('.tabbed-pane')?.shadowRoot?.querySelector('.tabbed-pane-header');
    assert.isOk(tabbedPaneHeader);
    assert.isTrue(tabbedPaneHeader.classList.contains('hidden'));
    detailsView.detach();
  });

  it('stops listening to TraceBounds changes when hidden', async function() {
    const parsedTrace = await TraceLoader.traceEngine(this, 'web-dev-with-commit.json.gz');
    const evalScriptEvent = allThreadEntriesInTrace(parsedTrace).find(event => {
      return event.name === Trace.Types.Events.Name.EVALUATE_SCRIPT && event.dur && event.dur > 2000;
    });
    assert.isOk(evalScriptEvent);

    const detailsView = Timeline.TimelineDetailsView.TimelineDetailsPane.makeEventWidget(
        evalScriptEvent,
        parsedTrace,
    );
    renderElementIntoDOM(detailsView);
    await doubleRaf();

    detailsView.detach();
    const setSelection = sinon.spy(detailsView, 'setSelection');
    const {min, max} = parsedTrace.data.Meta.traceBounds;
    const subBounds = Trace.Helpers.Timing.traceWindowFromMicroSeconds(
        min,
        Trace.Types.Timing.Micro(max - 2_000),
    );
    TraceBounds.TraceBounds.BoundsManager.instance().setMiniMapBounds(subBounds);
    sinon.assert.notCalled(setSelection);

    renderElementIntoDOM(detailsView);
    sinon.assert.calledOnce(setSelection);
    detailsView.detach();
  });

  it('reuses a provided entityMapper instance in setModel', async function() {
    const parsedTrace = await TraceLoader.traceEngine(this, 'web-dev-with-commit.json.gz');
    const detailsView = new Timeline.TimelineDetailsView.TimelineDetailsPane(mockViewDelegate);
    renderElementIntoDOM(detailsView);

    const mapper = new Trace.EntityMapper.EntityMapper(parsedTrace);
    await detailsView.setModel({
      parsedTrace,
      selectedEvents: null,
      eventToRelatedInsightsMap: null,
      entityMapper: mapper,
    });
    await raf();

    // Switch to the Bottom-up tab so its tree view is visible and populated.
    const bottomUpTab = detailsView.headerElement().querySelector<HTMLElement>('#tab-bottom-up');
    assert.isNotNull(bottomUpTab);
    bottomUpTab.dispatchEvent(new MouseEvent('mousedown', {button: 0, bubbles: true}));
    await raf();

    const treeViewElement = detailsView.element.querySelector('.timeline-tree-view');
    assert.isNotNull(treeViewElement);
    const treeView = UI.Widget.Widget.get(treeViewElement);
    assert.instanceOf(treeView, Timeline.TimelineTreeView.TimelineTreeView);
    assert.strictEqual(treeView.entityMapper(), mapper);
    detailsView.detach();
  });

  it('defers updating the summary view when another tab is active and updates when switching back', async function() {
    const parsedTrace = await TraceLoader.traceEngine(this, 'web-dev-with-commit.json.gz');
    const detailsView = new Timeline.TimelineDetailsView.TimelineDetailsPane(mockViewDelegate);
    renderElementIntoDOM(detailsView);

    await detailsView.setModel({
      parsedTrace,
      selectedEvents: allThreadEntriesInTrace(parsedTrace),
      eventToRelatedInsightsMap: null,
      entityMapper: null,
    });
    const bounds = Trace.Helpers.Timing.traceWindowMilliSeconds(parsedTrace.data.Meta.traceBounds);
    const initialSelection = Timeline.TimelineSelection.selectionFromRangeMilliSeconds(
        bounds.min,
        bounds.max,
    );
    await detailsView.setSelection(initialSelection);
    await raf();

    const detailsContentElement = detailsView.getDetailsContentElementForTest();
    const rangeSummaryElement = detailsContentElement.querySelector('devtools-widget');
    assert.isNotNull(rangeSummaryElement);
    const rangeSummaryWidget = UI.Widget.Widget.get(rangeSummaryElement);
    assert.isDefined(rangeSummaryWidget);

    // Switch to the Bottom-up tab.
    const bottomUpTab = detailsView.headerElement().querySelector<HTMLElement>('#tab-bottom-up');
    assert.isNotNull(bottomUpTab);
    bottomUpTab.dispatchEvent(new MouseEvent('mousedown', {button: 0, bubbles: true}));
    await raf();

    const requestUpdateSpy = sinon.spy(rangeSummaryWidget, 'requestUpdate');

    // Update the range selection while Bottom-up is active.
    const subRangeSelection = Timeline.TimelineSelection.selectionFromRangeMilliSeconds(
        bounds.min,
        Trace.Types.Timing.Milli(bounds.min + 1000),
    );
    await detailsView.setSelection(subRangeSelection);
    await raf();

    // Summary view should not have requested an update while Bottom-up is active.
    sinon.assert.notCalled(requestUpdateSpy);

    // Switch back to the Summary tab.
    const summaryTab = detailsView.headerElement().querySelector<HTMLElement>('#tab-details');
    assert.isNotNull(summaryTab);
    summaryTab.dispatchEvent(new MouseEvent('mousedown', {button: 0, bubbles: true}));
    await raf();

    // Summary view now requests an update when the tab becomes active.
    sinon.assert.called(requestUpdateSpy);
    detailsView.detach();
  });

  it('switches to Bottom-up grouped by third parties and expands matching entity from selectTab', async function() {
    const parsedTrace = await TraceLoader.traceEngine(this, 'web-dev-with-commit.json.gz');
    const detailsView = new Timeline.TimelineDetailsView.TimelineDetailsPane(mockViewDelegate);
    const mapper = new Trace.EntityMapper.EntityMapper(parsedTrace);
    const selectedEvents = allThreadEntriesInTrace(parsedTrace);
    renderElementIntoDOM(detailsView);

    await detailsView.setModel({
      parsedTrace,
      selectedEvents,
      eventToRelatedInsightsMap: null,
      entityMapper: mapper,
    });
    const bounds = Trace.Helpers.Timing.traceWindowMilliSeconds(parsedTrace.data.Meta.traceBounds);
    await detailsView.setSelection(Timeline.TimelineSelection.selectionFromRangeMilliSeconds(bounds.min, bounds.max));
    await raf();

    const thirdPartyTree = new Timeline.ThirdPartyTreeView.ThirdPartyTreeViewWidget();
    thirdPartyTree.setRange(bounds.min, bounds.max);
    thirdPartyTree.model = {selectedEvents, parsedTrace, entityMapper: mapper};
    const thirdPartyNode = thirdPartyTree.buildTree().children().get('Google Tag Manager');
    assert.isOk(thirdPartyNode);

    const gridNodeForEventSpy =
        sinon.spy(Timeline.TimelineTreeView.BottomUpTimelineTreeView.prototype, 'gridNodeForEvent');
    try {
      detailsView.selectTab(
          Timeline.TimelineDetailsView.Tab.BottomUp,
          thirdPartyNode,
          Timeline.TimelineTreeView.AggregatedTimelineTreeView.GroupBy.ThirdParties,
      );
      await raf();

      const bottomUpElement = detailsView.element.querySelector('.timeline-tree-view');
      assert.isNotNull(bottomUpElement);
      const bottomUpView = UI.Widget.Widget.get(bottomUpElement);
      assert.instanceOf(bottomUpView, Timeline.TimelineTreeView.BottomUpTimelineTreeView);
      const selectedNode = bottomUpView.dataGrid.selectedNode;
      assert.instanceOf(selectedNode, Timeline.TimelineTreeView.GridNode);
      assert.strictEqual(selectedNode.profileNode.id, 'Google Tag Manager');
      assert.isTrue(selectedNode.profileNode.events.includes(thirdPartyNode.event));
      assert.isTrue(selectedNode.expanded);
      sinon.assert.notCalled(gridNodeForEventSpy);
    } finally {
      gridNodeForEventSpy.restore();
      detailsView.detach();
    }
  });

  describe('warning row', () => {
    afterEach(() => {
      setColorScheme('light');
    });

    it('renders with theme-aware surface-error background in light and dark themes', async function() {
      const parsedTrace = await TraceLoader.traceEngine(this, 'simple-js-program.json.gz');
      const detailsView = new Timeline.TimelineDetailsView.TimelineDetailsPane(mockViewDelegate);
      detailsView.element.style.width = '600px';
      detailsView.element.style.height = '400px';
      renderElementIntoDOM(detailsView, {includeCommonStyles: true});

      const longTask = allThreadEntriesInTrace(parsedTrace).find(e => (e.dur || 0) > 1_000_000);
      assert.isOk(longTask);
      await detailsView.setModel({
        parsedTrace,
        selectedEvents: null,
        eventToRelatedInsightsMap: null,
        entityMapper: null,
      });
      const selection = Timeline.TimelineSelection.selectionFromEvent(longTask);
      await detailsView.setSelection(selection);
      await raf();

      const detailsContentElement = detailsView.getDetailsContentElementForTest();
      const warningRow = detailsContentElement.querySelector<HTMLElement>('.timeline-details-warning');
      assert.isNotNull(warningRow);

      setColorScheme('light');
      assert.strictEqual(getComputedStyle(warningRow).backgroundColor, 'rgb(252, 235, 235)');
      await assertScreenshot('timeline/timeline_details_warning_light.png');

      setColorScheme('dark');
      assert.strictEqual(getComputedStyle(warningRow).backgroundColor, 'rgb(78, 53, 52)');
      await assertScreenshot('timeline/timeline_details_warning_dark.png');

      detailsView.detach();
    });
  });

